using EduManageLms.Api.Application; using EduManageLms.Api.Common; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace EduManageLms.Api.Controllers; [ApiController][Route("api/v1")][Authorize]
public sealed class DashboardController(IDashboardService svc):ControllerBase{[HttpGet("admin/dashboard")][Authorize(Roles="Admin")]public async Task<ActionResult<ApiResponse<DashboardDto>>> Admin(CancellationToken ct)=>Ok(ApiResponse<DashboardDto>.Ok(await svc.AdminAsync(ct)));[HttpGet("lecturer/dashboard")][Authorize(Roles="Lecturer")]public async Task<ActionResult<ApiResponse<DashboardDto>>> Lecturer(CancellationToken ct)=>Ok(ApiResponse<DashboardDto>.Ok(await svc.LecturerAsync(User.LecturerCode()!,ct)));[HttpGet("student/dashboard")][Authorize(Roles="Student")]public async Task<ActionResult<ApiResponse<DashboardDto>>> Student(CancellationToken ct)=>Ok(ApiResponse<DashboardDto>.Ok(await svc.StudentAsync(User.StudentCode()!,ct)));}
